# -*- coding: utf-8 -*-
"""外部替身登记与证据分级（只定义结构与标签，不实现生产替身）。

原则（对应任务书与 E-acceptance.md）：
- 替身必须通过 A 提供的适配端口（face/LLM/push/OSS 等接口边界）注入被测系统，
  E 不自建任何生产实现，也不测内部函数。
- 场景执行前用 DoublesManifest 声明每个外部协作者的模式；证据标签按最保守口径：
  只要有一个关键外部依赖是 double，结论只能记 ``doubles_pass``；
  全部关键外部依赖为真实供应商/设备且观察到真实结果，才允许 ``real_pass``。
  模拟通过不得冒充真实设备停止、人脸连续性或手机实际收到通知。
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Iterable

#: 本版外部协作方（来源：运行组件说明/API 设计；不含内部实现细节）
DOUBLE_KINDS = ("face_algo", "llm_plan", "push_channel", "oss", "gimbal_device", "microcrystal")

#: 联调硬门槛：这些结论即使全 double 也必须另行真实验证，不能只记 doubles_pass
REAL_ONLY_CHECKPOINTS = ("设备实际停止", "人脸连续性", "手机实际收到通知", "真实算法准确率")


@dataclass(frozen=True)
class DependencyUsage:
    kind: str            # DOUBLE_KINDS 之一
    mode: str            # "double" | "real"
    note: str = ""

    def __post_init__(self) -> None:
        if self.kind not in DOUBLE_KINDS:
            raise ValueError(f"未登记的外部依赖类型：{self.kind}，允许：{DOUBLE_KINDS}")
        if self.mode not in ("double", "real"):
            raise ValueError(f"mode 必须是 double/real：{self.mode}")


@dataclass
class DoublesManifest:
    """场景运行声明：本次执行依赖哪些外部方、各自真实或替身。"""
    scenario_id: str
    usages: list[DependencyUsage] = field(default_factory=list)

    def add(self, kind: str, mode: str, note: str = "") -> "DoublesManifest":
        self.usages.append(DependencyUsage(kind=kind, mode=mode, note=note))
        return self

    def modes(self) -> set[str]:
        return {u.mode for u in self.usages}

    def evidence_tag(self) -> str:
        """返回 doubles_pass / real_pass / mixed / no_externals。"""
        m = self.modes()
        if not m:
            return "no_externals"
        if m == {"real"}:
            return "real_pass"
        if m == {"double"}:
            return "doubles_pass"
        return "mixed"  # 部分真实：按最保守口径呈现，需逐项注明未真实部分

    def assert_claimable(self, claim: str) -> None:
        """守卫：阻止把 doubles 结果申报为真实通过。"""
        if claim == "real_pass" and self.evidence_tag() != "real_pass":
            raise AssertionError(
                f"{self.scenario_id}: 外部依赖含替身/缺真实证据，只能记 "
                f"{self.evidence_tag()}，不得申报 real_pass")


def summarize(manifests: Iterable[DoublesManifest]) -> dict[str, int]:
    """汇总一批场景声明的标签计数（用于报告区分替身通过与真实通过）。"""
    out: dict[str, int] = {}
    for mf in manifests:
        tag = mf.evidence_tag()
        out[tag] = out.get(tag, 0) + 1
    return out

# -*- coding: utf-8 -*-
"""E 验收 pytest 插件：marker 注册、dependency_pending 统计、matrix 退出码。

由 backend/acceptance/conftest.py 经 pytest_plugins 加载（顶层 conftest 合法）。

规则：
- 场景测试在 gate=closed 时 skip，reason 前缀固定 ``dependency_pending: ``；
  本插件把这类 skip 与普通 skipped 分开统计，并在终端摘要输出
  ``PASSED=n DEPENDENCY_PENDING=m FAILED=k``。
- 模式来自环境变量 E_ACCEPTANCE_MODE（run.sh 注入）：
    selfcheck → 只跑框架自检，退出码保持 pytest 原生 0/1；
    matrix    → 若存在 dependency_pending 且无失败，最终退出码强制为 3（绝不 0）；
                若有失败则维持 1。未注入模式时按 matrix 处理（fail-safe，
                宁可 3 也不给假 0）。
"""
from __future__ import annotations

import os

import pytest

from framework.gate import PENDING_PREFIX

MARKERS = (
    ("sc_id", "场景编号标记，如 sc_id('SC-00-01')"),
    ("priority", "清单优先级 P0/P1"),
    ("scope", "验证范围：后端/集成/联调"),
    ("package", "负责业务工作包：B/C/D（可重复标记）"),
    ("deps", "开发对接项 D01-D08（可重复标记）"),
)


def pytest_configure(config: pytest.Config) -> None:
    for name, desc in MARKERS:
        config.addinivalue_line("markers", f"{name}(value): {desc}")
    config._e_acc = {"passed": 0, "failed": 0, "pending": 0, "skipped_other": 0}


def _counts(config: pytest.Config) -> dict[str, int]:
    return getattr(config, "_e_acc", {"passed": 0, "failed": 0, "pending": 0, "skipped_other": 0})


def _mode() -> str:
    return os.environ.get("E_ACCEPTANCE_MODE", "matrix")


@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_logreport(report: pytest.TestReport):
    outcome = yield
    cfg = pytest.Config  # placeholder to keep type checkers quiet
    rep = outcome.get_result()
    counts = getattr(rep.session.config, "_e_acc", None) if hasattr(rep, "session") else None
    if counts is None:  # pragma: no cover - defensive
        return
    if rep.when == "call" and rep.passed:
        counts["passed"] += 1
    elif rep.when != "call" and rep.skipped and PENDING_PREFIX in str(rep.longrepr or ""):
        counts["pending"] += 1
    elif rep.failed:
        counts["failed"] += 1
    elif rep.skipped:
        counts["skipped_other"] += 1


def pytest_terminal_summary(terminalreporter: "pytest.TerminalReporter",
                            exitstatus: int, config: pytest.Config) -> None:
    c = _counts(config)
    terminalreporter.write_sep("=", "E 验收统计")
    terminalreporter.write_line(
        f"PASSED={c['passed']} DEPENDENCY_PENDING={c['pending']} FAILED={c['failed']} "
        f"SKIPPED_OTHER={c['skipped_other']} MODE={_mode()}")
    if c["pending"]:
        terminalreporter.write_line(
            "说明：dependency_pending = A 基线未交付导致的依赖挂起，不是通过，也不是普通跳过。")


def pytest_sessionfinish(session: pytest.Session, exitstatus: int) -> None:
    if _mode() != "selfcheck":
        c = _counts(session.config)
        if c["failed"] > 0:
            session.exitstatus = pytest.ExitCode.TESTS_FAILED  # 维持 1
        elif c["pending"] > 0:
            session.exitstatus = 3  # 有挂起场景：绝不返回 0

