    """E 入口单实例锁：lockfile + PID 活性。返回 (ok, reason)。"""
    LOCK_FILE.parent.mkdir(parents=True, exist_ok=True)
    if LOCK_FILE.exists():
        parts = LOCK_FILE.read_text(encoding="utf-8").split()
