def canon_public(body):
    """完整公开响应规范化：仅递归排除逐请求字段 requestId，其余全部保留后逐字节比较。"""
    def strip(o):
        if isinstance(o, dict):
            return {k: strip(v) for k, v in o.items() if k != "requestId"}
        if isinstance(o, list):
            return [strip(x) for x in o]
        return o
