/** 普通评估行（非 report_ready）。 */
public UUID seedAssessment(UUID gimbalId, UUID memberId) {
    UUID id = UUID.randomUUID();
    jdbc.update("INSERT INTO skin_assessments (id, gimbal_id, member_id, status, source_request_id)"
